<script lang="ts">
  import { enhance } from '$app/forms';
  import { Upload, KeyRound, LockKeyhole, ArrowUp, ArrowUpRight, MessageCircle, ImagePlus, Pencil, Archive, RotateCcw, Check, X, Copy } from '@lucide/svelte';
  import GalleryShell from '$lib/components/GalleryShell.svelte';
  import GalleryLogin from '$lib/components/GalleryLogin.svelte';
  import GalleryPassphrase from '$lib/components/GalleryPassphrase.svelte';
  export let data; export let form;
  let pin:{fileId:string;x:number;y:number}|null=null;
  let showArchived=false,editingId='',draft='',busy='',selectedFiles:File[]=[],fileInput:HTMLInputElement,copied=false,sharingOpen=false;
  $: files=data.files.filter(file=>!!file.archived===showArchived);
  $: activeCount=data.files.filter(file=>!file.archived).length;
  $: archivedCount=data.files.filter(file=>!!file.archived).length;
  $: selectedName=pin?data.files.find(file=>file.id===pin?.fileId)?.name:'';
  function placePin(event:MouseEvent,fileId:string){const box=(event.currentTarget as HTMLElement).getBoundingClientRect();pin={fileId,x:Math.max(0,Math.min(1,(event.clientX-box.left)/box.width)),y:Math.max(0,Math.min(1,(event.clientY-box.top)/box.height))};}
  function pending(action:string){busy=action;return async({update,result}:any)=>{await update({reset:false});busy='';if(result.type==='success'){if(action==='comment'){draft='';pin=null;}if(action==='rename')editingId='';if(action==='rotate'){sharingOpen=false;(document.getElementById('gallery-access-form') as HTMLFormElement)?.reset();}if(action==='upload'){selectedFiles=[];fileInput.value='';}}};}
  async function copyLink(){try{await navigator.clipboard.writeText(window.location.href.split('?')[0]);copied=true;}catch{copied=false,sharingOpen=false;}}
</script>
<svelte:head><title>{data.authenticated?`${data.person} · Gallery`:'Private gallery'} | mikeblocky.com</title><meta name="robots" content="noindex,nofollow,noarchive,noimageindex" /></svelte:head>
<GalleryShell title={data.authenticated?data.person:'Private gallery'} meta={data.authenticated?`${activeCount} ${activeCount===1?'image':'images'} · ${data.admin?'You manage this gallery':'View & comment'}`:'Password protected'} detail>
  <svelte:fragment slot="actions">{#if data.authenticated}<details class="gallery-sharing" bind:open={sharingOpen}><summary class="gallery-button"><KeyRound size={17} />Access</summary><div class="gallery-sharing-panel"><button type="button" class="gallery-button" on:click={copyLink}>{#if copied}<Check size={16} />Link copied{:else}<Copy size={16} />Copy gallery link{/if}</button><form id="gallery-access-form" class="gallery-fields" method="POST" action="?/rotate" use:enhance={()=>pending('rotate')}>
      {#if !data.admin}<label for="current-password">Current password</label><input id="current-password" name="currentPassword" type="password" autocomplete="current-password" required maxlength="256" />{/if}
      <label for="new-password">New password</label><input id="new-password" name="password" type="password" autocomplete="new-password" required minlength="10" maxlength="128" aria-describedby="password-help" />
      <label for="confirm-password">Confirm password</label><input id="confirm-password" name="confirmPassword" type="password" autocomplete="new-password" required minlength="10" maxlength="128" />
      <small id="password-help">10�128 characters. Other sessions will be signed out.</small><button class="gallery-button primary" disabled={!!busy}>{busy==='rotate'?'Saving�':'Save password'}</button>
    </form></div></details>{#if data.admin}<button class="gallery-button primary" type="button" on:click={()=>fileInput?.click()}><Upload size={17} />Add images</button>{:else}<form method="POST" action="?/lock"><button class="gallery-button quiet"><LockKeyhole size={16} />Lock</button></form>{/if}{/if}</svelte:fragment>
  {#if form?.passwordChanged}<p class="gallery-notice" role="status">Password updated.</p>{/if}
  {#if form?.error}<p class="gallery-notice error" role="alert">{form.error}</p>{/if}
  {#if data.authenticated}
    {#if form?.password}<GalleryPassphrase password={form.password} folderId={data.id} />{/if}
    {#if data.admin}<form method="POST" action="?/upload" enctype="multipart/form-data" use:enhance={()=>pending('upload')}><input class="gallery-visually-hidden" bind:this={fileInput} id="gallery-upload" aria-label="Choose gallery images" name="image" type="file" accept="image/png,image/jpeg,image/webp" multiple on:change={event=>selectedFiles=Array.from(event.currentTarget.files||[])} />{#if selectedFiles.length}<div class="gallery-upload-selection"><div><strong>{selectedFiles.length} {selectedFiles.length===1?'image':'images'} ready</strong><p>{selectedFiles.map(file=>file.name).join(', ')}</p></div><div class="gallery-card-actions"><button class="gallery-button primary" disabled={!!busy}>{busy==='upload'?'Uploading…':'Upload'}</button><button type="button" class="gallery-icon" aria-label="Cancel upload" on:click={()=>{selectedFiles=[];fileInput.value='';}}><X size={16} /></button></div></div>{/if}</form>{/if}
    <div class="gallery-split"><section aria-label="Gallery images">
      {#if data.admin&&archivedCount}<div class="gallery-toolbar"><span></span><button type="button" class="gallery-button quiet" on:click={()=>{showArchived=!showArchived;pin=null;}}><Archive size={15} />{showArchived?'Back to gallery':`Archived (${archivedCount})`}</button></div>{/if}
      <div class="gallery-tiles">{#each files as file}<figure class="gallery-tile"><button type="button" class="gallery-photo" class:selected={pin?.fileId===file.id} aria-label={`Add a note to ${file.name}`} on:click={event=>placePin(event,file.id)}><img src={`/commissions/files/${data.id}/image/${file.id}`} alt={file.name} loading="lazy" />{#each data.comments.filter(comment=>comment.file_id===file.id) as comment,index}<span class="gallery-pin" style={`left:${comment.x!*100}%;top:${comment.y!*100}%`} title={comment.body}>{index+1}</span>{/each}{#if pin?.fileId===file.id}<span class="gallery-pin pending" style={`left:${pin.x*100}%;top:${pin.y*100}%`}>+</span>{/if}</button><figcaption class="gallery-caption"><div><strong>{file.name}</strong><a class="gallery-text-link" href={`/commissions/files/${data.id}/image/${file.id}`} target="_blank" rel="noreferrer">Full size<ArrowUpRight size={12} /></a></div>{#if data.admin}<div class="gallery-card-actions"><button type="button" class="gallery-icon" aria-label={`Rename ${file.name}`} title="Rename image" on:click={()=>editingId=editingId===file.id?'':file.id}><Pencil size={15} /></button><form method="POST" action="?/archive" use:enhance={()=>pending('archive')}><input type="hidden" name="fileId" value={file.id} /><button class="gallery-icon" disabled={!!busy} aria-label={`${file.archived?'Restore':'Archive'} ${file.name}`} title={file.archived?'Restore image':'Archive image'}>{#if file.archived}<RotateCcw size={15} />{:else}<Archive size={15} />{/if}</button></form></div>{/if}</figcaption>{#if editingId===file.id}<form method="POST" action="?/rename" class="gallery-rename" use:enhance={()=>pending('rename')}><input type="hidden" name="fileId" value={file.id} /><input name="name" aria-label="Image name" value={file.name} required maxlength="120" /><button class="gallery-icon" disabled={!!busy} aria-label="Save image name"><Check size={16} /></button><button class="gallery-icon" type="button" aria-label="Cancel rename" on:click={()=>editingId=''}><X size={16} /></button></form>{/if}</figure>{/each}</div>
      {#if !files.length}<div class="gallery-empty"><ImagePlus size={32} strokeWidth={1.4} /><h2>{showArchived?'No archived images':'No images yet'}</h2></div>{/if}
    </section><aside class="gallery-notes" aria-label="Gallery comments"><h2>Conversation<small>{data.comments.length||''}</small></h2><form method="POST" action="?/comment" class="gallery-composer" use:enhance={()=>pending('comment')}><input type="hidden" name="fileId" value={pin?.fileId||''} /><input type="hidden" name="x" value={pin?.x??''} /><input type="hidden" name="y" value={pin?.y??''} />{#if pin}<div class="gallery-pin-label"><span>Note on {selectedName}</span><button type="button" class="gallery-icon" aria-label="Cancel annotation" on:click={()=>pin=null}><X size={15} /></button></div>{/if}<label class="gallery-visually-hidden" for="gallery-comment">{pin?'Image note':'Comment'}</label><textarea id="gallery-comment" name="body" bind:value={draft} placeholder={pin?'What should change here?':'Leave a comment…'} required maxlength="2000" rows="3"></textarea><div class="gallery-composer-footer"><span>{pin?'Pinned to the image':'Click an image to pin a note'}</span><button class="gallery-button primary" disabled={!!busy||!draft.trim()} aria-label={pin?'Post annotation':'Post comment'}><ArrowUp size={16} />{busy==='comment'?'Sending…':'Send'}</button></div></form>{#each data.comments as comment}<article class="gallery-note"><header><strong>{comment.author}</strong><time datetime={comment.created_at}>{new Date(comment.created_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</time></header>{#if comment.file_id}<small>Image note</small>{/if}<p>{comment.body}</p></article>{/each}</aside></div>
  {:else}<GalleryLogin />{/if}
</GalleryShell>
